#pragma once
static void checkSpatialTemplates(App& app,const std::string& dir){
    auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("spatial template: "+why);};
    const std::set<std::string> categories={"有机光催化剂","吖啶鎓与吡喃鎓光催化剂","吩噻嗪与吩噁嗪光催化剂","芳烃光敏剂","芳香酮光敏剂","染料光敏剂","金属配合物光催化剂"};
    const std::set<std::string> extra={"EosinY-Na2","PPh3","OPPh3","PCy3"};
    auto reset=[&](){app.s.cancel();app.s.doc=Document();app.s.history.clear();app.s.selected.clear();app.s.input.bindDocument(app.s.doc.id());app.s.refresh();};
    auto styles=[](const Document& d){std::vector<std::pair<int,double>> values;for(const auto& b:d.bonds().records())if(b.isAlive()){double width=0;if(auto w=d.extensions(ObjectRef(ObjectKind::Bond,b.id)).findValue("pst.attr.BoldWidth"))width=std::atof(w->c_str());values.push_back({int(b.display),width});}return values;};
    std::vector<std::shared_ptr<Session>> heroes;TemplateLibraryModel model;model.title="立体模板";int total=0,depthAtoms=0;
    for(size_t index=0;index<reagentEntries().size();++index){const auto& entry=reagentEntries()[index];std::string alias=entry.alias;alias=alias.substr(0,alias.find(' '));if(!categories.count(entry.category)&&!extra.count(alias))continue;
        auto source=readReagentTemplate(int(index));const auto expected=studio::analyze(source->doc,source->all());require(expected.valid,"source formula: "+alias);
        int bold=0,solid=0,hashed=0,zCount=0;for(const auto& a:source->doc.atoms().records())if(a.isAlive()){require(!source->doc.extensions(ObjectRef(ObjectKind::Atom,a.id)).findValue("studio.nickname.fragment"),"preview contains full editable skeleton: "+alias);zCount+=source->doc.extensions(ObjectRef(ObjectKind::Atom,a.id)).findValue("studio.atom.z")!=nullptr;}
        for(const auto& b:source->doc.bonds().records())if(b.isAlive()){bold+=b.display==BondDisplay::Bold;solid+=b.display==BondDisplay::Wedge;hashed+=b.display==BondDisplay::WedgeHash;if(b.display==BondDisplay::Bold){auto w=source->doc.extensions(ObjectRef(ObjectKind::Bond,b.id)).findValue("pst.attr.BoldWidth");require(w&&std::abs(std::atof(w->c_str())-1.332)<1e-6,"restrained bold width: "+alias);}}
        if(alias=="Ir(ppy)3"){require(expected.plain=="C33H24IrN3"&&solid==2&&hashed==2,"fac Ir(ppy)3 formula and front/rear wedges");ObjectId metal=kInvalidObjectId;for(const auto& a:source->doc.atoms().records())if(a.isAlive()&&a.element==77)metal=a.id;require(metal!=kInvalidObjectId&&source->doc.incidentBonds(metal).size()==6,"six connected Ir coordination bonds");}
        else require(bold>0&&zCount==int(source->doc.stats().aliveAtoms),"standard ring depth and bold edges: "+alias);
        const auto expectedStyles=styles(source->doc);const auto stats=source->doc.stats();std::vector<double> expectedDepth;for(const auto& a:source->doc.atoms().records())if(a.isAlive())if(auto z=source->doc.extensions(ObjectRef(ObjectKind::Atom,a.id)).findValue("studio.atom.z"))expectedDepth.push_back(std::atof(z->c_str()));const double sourceBondLength=source->doc.defaultBondLength();
        reset();const auto before=app.s.doc.digest();app.bioSource=source;app.placeReagent(Vec2(100,100));require(app.s.doc.stats().aliveAtoms==stats.aliveAtoms&&app.s.doc.stats().aliveBonds==stats.aliveBonds,"placement retains graph: "+alias);auto actual=studio::analyze(app.s.doc,app.s.all());require(actual.valid&&actual.plain==expected.plain,"placement preserves formula: "+alias);require(styles(app.s.doc)==expectedStyles,"placement preserves wedge direction and bold widths: "+alias);
        int insertedZ=0,ignoredNitrogens=0;for(const auto& a:app.s.doc.atoms().records())if(a.isAlive()){const auto& ext=app.s.doc.extensions(ObjectRef(ObjectKind::Atom,a.id));if(a.element==7&&ext.findValue("pst.attr.IgnoreWarnings"))++ignoredNitrogens;if(auto z=ext.findValue("studio.atom.z")){require(insertedZ<int(expectedDepth.size())&&std::abs(std::atof(z->c_str())-expectedDepth[insertedZ]*app.s.doc.defaultBondLength()/sourceBondLength)<1e-8,"depth scales numerically with XY: "+alias);++insertedZ;}}require(insertedZ==zCount,"template scaling and insertion retain xyz: "+alias);if(alias=="Ir(ppy)3")require(ignoredNitrogens==3,"only coordinated pyridyl nitrogen uses the standard drawing warning override");depthAtoms+=insertedZ;
        const auto after=app.s.doc.digest();require(app.s.undo().ok()&&app.s.doc.digest()==before,"one placement undo: "+alias);require(app.s.undo(true).ok()&&app.s.doc.digest()==after,"placement redo: "+alias);
        const auto file=dir+"/spatial-"+alias+".cdxml";require(app.s.save(file,true).ok(),"export: "+alias);Session reopened;require(reopened.open(file).ok(),"reopen: "+alias);require(styles(reopened.doc)==expectedStyles,"CDXML preserves styles: "+alias);auto restored=studio::analyze(reopened.doc,reopened.all());require(restored.valid&&restored.plain==expected.plain,"CDXML preserves chemistry: "+alias);
        if(alias=="4CzIPN"||alias=="4DPAIPN"||alias=="Ir(ppy)3"||alias=="PPh3"||alias=="OPPh3"||alias=="PCy3"){auto hero=std::make_shared<Session>();hero->doc=app.s.doc;hero->refresh();int i=int(heroes.size());heroes.push_back(hero);model.parents.emplace_back(entry.title,alias,alias,entry.category,i,1);model.variants.emplace_back(i,"立体结构",alias);app.s.selected.clear();app.s.fit();app.invalidate();app.screenshot(dir+"/spatial-"+alias+".png");}
        ++total;
    }
    require(total==42&&heroes.size()==6,"39 photosensitizers and three bulky phosphines");model.load=[heroes](int index){return heroes.at(size_t(index));};
    Bitmap sheet(1500,1100,PixelFormat32bppARGB);Graphics g(&sheet);g.SetPageUnit(UnitPixel);g.Clear(white);g.ScaleTransform(2,2);g.SetSmoothingMode(SmoothingModeAntiAlias);
    for(int i=0;i<6;++i){float x=float(i%3)*250,y=float(i/3)*275;model.paint(g,i,RectF(x+12,y+8,226,230));require(!model.failures.count(i),"native thumbnail rendering");txt(g,model.parents[i].english,RectF(x+8,y+240,234,28),13,ink,true,true);}
    UINT count=0,bytes=0;GetImageEncodersSize(&count,&bytes);std::vector<uint8_t> codecsData(bytes);auto codecs=(ImageCodecInfo*)codecsData.data();GetImageEncoders(count,bytes,codecs);bool saved=false;for(UINT i=0;i<count;++i)if(wcscmp(codecs[i].MimeType,L"image/png")==0){saved=sheet.Save(W(dir+"/spatial-template-gallery.png").c_str(),&codecs[i].Clsid,0)==Ok;break;}require(saved,"save review gallery");
    reset();std::ofstream(dir+"/spatial-template-checks.json")<<"{\"templates\":"<<total<<",\"photosensitizers\":39,\"bulky_phosphines\":3,\"depth_atoms\":"<<depthAtoms<<",\"full_editable_skeletons\":true,\"formula_and_graph\":true,\"placement_scale_styles\":true,\"undo_redo\":true,\"cdxml_roundtrip\":true,\"ir_six_coordination_bonds\":true,\"ir_front_and_rear_wedges\":true,\"native_thumbnail_gallery\":true}";
}
